function makeCandidate(input) {
  const portfolioMeta = selectedPortfolioMeta[input.id] || {};
  const evidence = [
    { id: `${input.id}-E1`, type: "demand", claim: input.demand, url: input.evidenceUrl || input.url, observedAt },
    { id: `${input.id}-E2`, type: "interaction", claim: input.interaction, url: input.evidenceUrl || input.url, observedAt },
    { id: `${input.id}-E3`, type: "source_rows", claim: input.rows, url: input.url, observedAt },
    { id: `${input.id}-E4`, type: "creator_business", claim: input.creatorValue, url: input.url, observedAt },
    { id: `${input.id}-E5`, type: "value_delta", claim: input.valueDelta, url: input.url, observedAt, evidenceClass: "internal_expert_judgment" },
    { id: `${input.id}-E6`, type: "portfolio", claim: input.portfolio, url: input.url, observedAt, evidenceClass: "internal_expert_judgment" },
  ];
  const keys = Object.keys(scoreWeights);
  const scores = Object.fromEntries(keys.map((key, index) => [key, {
    points: input.points[index],
    max: scoreWeights[key],
    comment: [input.demand, input.interaction, input.rows, input.creatorValue, input.valueDelta, input.portfolio][index],
    evidenceRefs: [`${input.id}-E${index + 1}`],
  }]));
  const total = Object.values(scores).reduce((sum, score) => sum + score.points, 0);
  const hardGates = { ...defaultPassGates, ...(input.gates || {}) };
  const gatesPass = Object.values(hardGates).every((value) => String(value).startsWith("pass"));
  const qualified = total >= 80 && gatesPass;
  return {
    candidateId: input.id,
    title: input.title,
    canonicalUrl: input.url,
    provider: input.provider,
    providerType: input.providerType,
    locale: input.locale,
    sourceFormat: input.sourceFormat,
    evidenceLane: input.lane,
    priorUse: input.priorUse,
    userMoment: input.userMoment || portfolioMeta.userMoment || "candidate_specific",
    contentRole: input.contentRole || portfolioMeta.contentRole || "candidate",
    actualRowCreatorTemplate: input.actualRowCreatorTemplate ?? portfolioMeta.actualRowCreatorTemplate ?? false,
    sourceStatus: input.sourceStatus || "opened_complete",
    evidence,
    scores,
    computedTotal: total,
    hardGates,
    hardGateEvidence: {
      source: [`${input.id}-E3`],
      rights: [`${input.id}-E3`],
      locale: [`${input.id}-E1`],
      safety: [`${input.id}-E3`],
      oneJob: [`${input.id}-E3`, `${input.id}-E5`],
      naturalArtifact: [`${input.id}-E5`],
    },
    interactionEvidenceType: input.lane === "official_high_intent" ? "official_high_intent_substitute" : "direct_visible_interaction_or_reuse_signal",
    rights: input.rights || {
      personalConversion: "allowed_link_based",
      publicCatalog: "review_required",
    },
    valueDelta: {
      sourceLinkOnlyLimit: input.linkLimit,
      persistentState: input.persistentState,
      returnMoment: input.returnMoment,
      naturalArtifact: input.artifact,
    },
    qualified,
    selection: input.selection || (qualified ? "qualified_not_selected" : "rejected"),
    rejectionReason: input.rejectionReason || null,
    duplicateEvidenceReuse: "Demand and interaction use separate evidence types; official high-intent substitution is explicitly labeled.",
  };
}

